package dev.aegisac;
import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import java.util.logging.*;
public final class DispatcherHistoryRegressionTest {
 static int n;static void require(boolean ok,String why){n++;if(!ok)throw new AssertionError(why);}
 public static void main(String[] args)throws Exception{
  List<Runnable> q=new ArrayList<>();BoundedDispatcher bounded=new BoundedDispatcher(2);require(bounded.submit(q::add,()->{}),"First rejected");require(bounded.submit(q::add,()->{}),"Second rejected");require(!bounded.submit(q::add,()->{}),"Queue unbounded");q.removeFirst().run();require(bounded.pending()==1,"Pending count leaked");require(bounded.submit(q::add,()->{throw new IllegalStateException();}),"Freed slot unavailable");for(Runnable r:q)try{r.run();}catch(IllegalStateException expected){}require(bounded.pending()==0,"Exception leaked queue slot");require(!bounded.submit(r->{throw new RejectedExecutionException();},()->{})&&bounded.pending()==0,"Executor rejection leaked slot");
  q.clear();SanctionDispatcher d=new SanctionDispatcher();UUID id=UUID.randomUUID();int[] actions={0};d.submit(id,q::add,()->actions[0]++);require(!d.submit(id,q::add,()->actions[0]++),"Duplicate accepted");d.forget(id);d.submit(id,q::add,()->actions[0]++);q.removeFirst().run();require(actions[0]==0&&d.pending()==1,"Old task punished a new session");q.removeFirst().run();require(actions[0]==1&&d.pending()==0,"New session task lost");
  d.submit(id,q::add,()->actions[0]++);d.clear();q.removeFirst().run();require(actions[0]==1&&d.pending()==0,"Pause replayed pending action");
  Path folder=Files.createTempDirectory("history-r14-");Logger log=Logger.getLogger("R14History");ConfirmedHistory h=new ConfirmedHistory(folder.resolve("history.properties"),log);for(int i=0;i<900;i++)h.append(id,"Player","DETECTION","item"+i);require(h.size()==512&&h.latest(id,50).getFirst().reason().equals("item899"),"History not bounded/ordered");h.close();h=new ConfirmedHistory(folder.resolve("history.properties"),log);require(h.size()==512&&h.latest(id,1).getFirst().reason().equals("item899"),"History restart failed");h.clear(id);h.close();h=new ConfirmedHistory(folder.resolve("history.properties"),log);require(h.size()==0,"History clear not durable");h.close();
  NativeSession.manualExempt(id,System.currentTimeMillis()+60000);require(NativeSession.exempt(id),"Exemption not applied");NativeSession.forget(id);require(!NativeSession.exempt(id),"Session exemption leaked");NativeSession.manualExempt(id,1);require(!NativeSession.exempt(id),"Expired exemption remained");
  NativeSession.beginReset(id);require(NativeSession.resetting(id),"Reset guard missing");NativeSession.forget(id);require(!NativeSession.resetting(id),"Reset guard leaked across disconnect");
  Object oldReset=NativeSession.beginReset(id);Object newReset=NativeSession.beginReset(id);NativeSession.finishReset(id,oldReset);require(NativeSession.resetting(id),"Old session released a new reset guard");NativeSession.finishReset(id,newReset);require(!NativeSession.resetting(id),"Matching reset guard leaked");
  var event=new ac.grim.grimac.api.event.events.CommandExecuteEvent(null,null,"detail","expanded");NativeOutputBridge.tag(event,"[aegis]");require(NativeOutputBridge.action(event).equals("[aegis]")&&event.getCommand().equals("expanded"),"Original command text changed");require(NativeOutputBridge.action(event).equals("expanded"),"Native action replayed");
  var alerts=new ac.grim.grimac.manager.AlertManagerImpl();var text=ac.grim.grimac.shaded.kyori.adventure.text.Component.text("raw failed check");require(alerts.sendAlert(text,null).isEmpty()&&alerts.sendVerbose(text,null).isEmpty()&&alerts.sendBrand(text,null).isEmpty()&&!alerts.hasVerboseListeners(),"Raw native output escaped");
  System.out.println("PASS: "+n+" bounded queue, session, ledger and output assertions");
 }
}
